/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Poly, Rational, Sym, add, expand, expandFunc, ff, fn, mul, pow, rf } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.functions.combinatorial.factorials", () => {
  it("ff(x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(fn('ff', [x, Rational.of(0n, 1n, { gcd: 1n })]))).toBe('1');
  });
  it("ff(5, 5)", () => {
    expect(sympyStr(fn('ff', [Rational.of(5n, 1n, { gcd: 1n }), Rational.of(5n, 1n, { gcd: 1n })]))).toBe('120');
  });
  it("ff(x, 5) == x*(x - 1)*(x - 2)*(x - 3)*(x - 4)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, add(Rational.of(-1n, 1n, { gcd: 1n }), x), add(Rational.of(-4n, 1n, { gcd: 1n }), x), add(Rational.of(-3n, 1n, { gcd: 1n }), x), add(Rational.of(-2n, 1n, { gcd: 1n }), x)).equals(mul(x, add(Rational.of(-1n, 1n, { gcd: 1n }), x), add(Rational.of(-4n, 1n, { gcd: 1n }), x), add(Rational.of(-3n, 1n, { gcd: 1n }), x), add(Rational.of(-2n, 1n, { gcd: 1n }), x))))).toBe('True');
  });
  it("ff(Poly(x**2, x), 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(ff(Poly.from(pow(x, Rational.of(2n, 1n, { gcd: 1n })), [x], { domain: 'ZZ', pure: false }), Rational.of(2n, 1n, { gcd: 1n })))).toBe('Poly(x**4 - 2*x**3 + x**2, x, domain=\'ZZ\')');
  });
  it("ff(n, n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('ff', [n, n]))).toBe('factorial(n)');
  });
  it("rf(x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(fn('rf', [x, Rational.of(0n, 1n, { gcd: 1n })]))).toBe('1');
  });
  it("rf(1, 5)", () => {
    expect(sympyStr(fn('rf', [Rational.of(1n, 1n, { gcd: 1n }), Rational.of(5n, 1n, { gcd: 1n })]))).toBe('120');
  });
  it("rf(x, 5) == x*(1 + x)*(2 + x)*(3 + x)*(4 + x)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, add(Rational.of(1n, 1n, { gcd: 1n }), x), add(Rational.of(2n, 1n, { gcd: 1n }), x), add(Rational.of(3n, 1n, { gcd: 1n }), x), add(Rational.of(4n, 1n, { gcd: 1n }), x)).equals(mul(x, add(Rational.of(1n, 1n, { gcd: 1n }), x), add(Rational.of(2n, 1n, { gcd: 1n }), x), add(Rational.of(3n, 1n, { gcd: 1n }), x), add(Rational.of(4n, 1n, { gcd: 1n }), x))))).toBe('True');
  });
  it("rf(Poly(x**3, x), 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(rf(Poly.from(pow(x, Rational.of(3n, 1n, { gcd: 1n })), [x], { domain: 'ZZ', pure: false }), Rational.of(2n, 1n, { gcd: 1n })))).toBe('Poly(x**6 + 3*x**5 + 3*x**4 + x**3, x, domain=\'ZZ\')');
  });
  it("binomial(15, 8)", () => {
    expect(sympyStr(fn('binomial', [Rational.of(15n, 1n, { gcd: 1n }), Rational.of(8n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('6435');
  });
  it("binomial(n, -1)", () => {
    const n = new Sym('n', { integer: true, positive: true });
    expect(sympyStr(fn('binomial', [n, Rational.of(-1n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('0');
  });
  it("binomial(Rational(5, 4), 3)", () => {
    expect(sympyStr(fn('binomial', [Rational.of(5n, 4n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('-5/128');
  });
  it("binomial(Rational(-5, 4), 3)", () => {
    expect(sympyStr(fn('binomial', [Rational.of(-5n, 4n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('-195/128');
  });
  it("binomial(n, 3)", () => {
    const n = new Sym('n', { integer: true, positive: true });
    expect(sympyStr(fn('binomial', [n, Rational.of(3n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('binomial(n, 3)');
  });
  it("binomial(n, 3).expand(func=True)", () => {
    const n = new Sym('n', { positive: true, integer: true });
    expect(sympyStr(expand(fn('binomial', [n, Rational.of(3n, 1n, { gcd: 1n })]), { func: true }))).toBe('n**3/6 - n**2/2 + n/3');
  });
  it("expand_func(binomial(n, 3))", () => {
    const n = new Sym('n', { positive: true, integer: true });
    expect(sympyStr(expandFunc(fn('binomial', [n, Rational.of(3n, 1n, { gcd: 1n })])))).toBe('n*(n - 2)*(n - 1)/6');
  });
  it("Mod(binomial(156675, 4433, evaluate=False), 10**5 + 3)", () => {
    expect(sympyStr(Rational.of(28625n))).toBe('28625');
  });
  it("Mod(binomial(10**18, 10**12, evaluate=False), (10**5 + 3)**2)", () => {
    expect(sympyStr(Rational.of(3744312326n))).toBe('3744312326');
  });
  it("factorial(0)", () => {
    expect(sympyStr(fn('factorial', [Rational.of(0n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('1');
  });
  it("factorial(7)", () => {
    expect(sympyStr(fn('factorial', [Rational.of(7n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('5040');
  });
  it("factorial(-2)", () => {
    expect(sympyStr(fn('factorial', [Rational.of(-2n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('zoo');
  });
  it("factorial(n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('factorial', [n], { evaluate: true }))).toBe('factorial(n)');
  });
  it("factorial(2*n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('factorial', [mul(Rational.of(2n, 1n, { gcd: 1n }), n)], { evaluate: true }))).toBe('factorial(2*n)');
  });
  it("factorial(S(1)/2)", () => {
    expect(sympyStr(fn('factorial', [Rational.of(1n, 2n, { gcd: 1n })], { evaluate: true }))).toBe('factorial(1/2)');
  });
  it("factorial2(n + 1)", () => {
    const n = new Sym('n');
    expect(sympyStr(fn('factorial2', [add(Rational.of(1n, 1n, { gcd: 1n }), n)], { evaluate: true }))).toBe('factorial2(n + 1)');
  });
  it("factorial2(5)", () => {
    expect(sympyStr(fn('factorial2', [Rational.of(5n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('15');
  });
  it("factorial2(-1)", () => {
    expect(sympyStr(fn('factorial2', [Rational.of(-1n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('1');
  });
  it("factorial2(-5)", () => {
    expect(sympyStr(fn('factorial2', [Rational.of(-5n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('1/3');
  });
  it("subfactorial(n + 1)", () => {
    const n = new Sym('n');
    expect(sympyStr(fn('subfactorial', [add(Rational.of(1n, 1n, { gcd: 1n }), n)], { evaluate: true }))).toBe('subfactorial(n + 1)');
  });
  it("subfactorial(5)", () => {
    expect(sympyStr(fn('subfactorial', [Rational.of(5n, 1n, { gcd: 1n })], { evaluate: true }))).toBe('44');
  });
  it("n", () => {
    const n = new Sym('n');
    expect(sympyStr(n)).toBe('n');
  });
});
